macro_rules! rand {
    () => {
        mod rand { use std :: cell :: Cell ; mod loom { # [cfg (not (loom))] pub (crate) mod rand { use std :: collections :: hash_map :: RandomState ; use std :: hash :: BuildHasher ; use std :: sync :: atomic :: AtomicU32 ; use std :: sync :: atomic :: Ordering :: Relaxed ; static COUNTER : AtomicU32 = AtomicU32 :: new (1) ; pub (crate) fn seed () -> u64 { RandomState :: new () . hash_one (COUNTER . fetch_add (1 , Relaxed)) } } # [cfg (loom)] pub (crate) mod rand { pub (crate) fn seed () -> u64 { 1 } } } # [doc = " Fast random number generate"] # [doc = ""] # [doc = " Implement `xorshift64+`: 2 32-bit `xorshift` sequences added together."] # [doc = " Shift triplet `[17,7,16]` was calculated as indicated in Marsaglia's"] # [doc = " `Xorshift` paper: <https://www.jstatsoft.org/article/view/v008i14/xorshift.pdf>"] # [doc = " This generator passes the SmallCrush suite, part of TestU01 framework:"] # [doc = " <http://simul.iro.umontreal.ca/testu01/tu01.html>"] # [derive (Debug)] pub (crate) struct FastRand { one : Cell < u32 > , two : Cell < u32 > , } impl FastRand { # [doc = " Initialize a new, thread-local, fast random number generator."] pub (crate) fn new (seed : u64) -> FastRand { let one = (seed >> 32) as u32 ; let mut two = seed as u32 ; if two == 0 { two = 1 ; } FastRand { one : Cell :: new (one) , two : Cell :: new (two) , } } pub (crate) fn fastrand_n (& self , n : u32) -> u32 { let mul = (self . fastrand () as u64) . wrapping_mul (n as u64) ; (mul >> 32) as u32 } fn fastrand (& self) -> u32 { let mut s1 = self . one . get () ; let s0 = self . two . get () ; s1 ^= s1 << 17 ; s1 = s1 ^ s0 ^ s1 >> 7 ^ s0 >> 16 ; self . one . set (s0) ; self . two . set (s1) ; s0 . wrapping_add (s1) } } pub (crate) fn thread_rng_n (n : u32) -> u32 { thread_local ! { static THREAD_RNG : FastRand = FastRand :: new (loom :: rand :: seed ()) ; } THREAD_RNG . with (| rng | rng . fastrand_n (n)) } }
    };
}

rand!();